let pairIndex=0,pairTarget=0,pairHeard=false;
function renderPair(){stopSpeech();const pair=PAIRS[pairIndex];pairTarget=Math.floor(Math.random()*2);pairHeard=false;$('#activity').innerHTML='<h3>¿Qué palabra escuchaste?</h3><p id="pairLabel"></p><button id="playPair" class="primary">'+HablaIcons.svg('sound')+' Escuchar una palabra</button><div id="pairChoices" class="pair-buttons inline"></div><p id="pairFeedback" role="status"></p><button id="nextPair">Otro par →</button>';$('#pairLabel').textContent=pair[2]+'. Escuchá y elegí.';for(const [i,w]of pair.slice(0,2).entries()){const b=document.createElement('button');b.textContent=w;b.onclick=()=>{if(!pairHeard){$('#pairFeedback').textContent='Primero escuchá la palabra. Si no hay voz disponible, practicá ambos modelos con un acompañante.';return}$('#pairFeedback').textContent=i===pairTarget?'¡Esa es la palabra que sonó!':'Escuchá otra vez y compará los sonidos.';if(i===pairTarget){record('Escucha de pares',w);$$('#pairChoices button').forEach(x=>x.disabled=true)}};$('#pairChoices').append(b)}$('#playPair').onclick=()=>{pairHeard=false;speak(pair[pairTarget],()=>{pairHeard=true;if($('#pairFeedback'))$('#pairFeedback').textContent='Ahora elegí la palabra que escuchaste.';});};$('#nextPair').onclick=()=>{pairIndex=(pairIndex+1)%PAIRS.length;renderPair()}}
function ensureAudio(){if(audioCapture)return;audioCapture=HablaAudio.create({getStream:()=>navigator.mediaDevices.getUserMedia({audio:true}),makeRecorder:stream=>new MediaRecorder(stream),onStatus:status=>{const button=$('#recordAudio'),label=$('#recordStatus');if(!button||!label)return;button.disabled=status==='pending';button.textContent=status==='recording'?'■ Detener grabación':status==='ready'?'● Grabar otra vez':'● Grabar mi voz';label.textContent=({pending:'Esperando permiso del micrófono…',recording:'Grabando… se detiene a los 30 segundos.',ready:'Escuchá tu grabación. No se evalúa automáticamente la pronunciación.',error:'No se pudo grabar. Revisá los permisos o continuá sin micrófono.'})[status];},onComplete:blob=>{const audio=$('#playback'),button=$('#downloadAudio');if(!audio||!button)return;if(audioURL)URL.revokeObjectURL(audioURL);audioURL=URL.createObjectURL(blob);audio.src=audioURL;audio.hidden=false;button.hidden=false;button.onclick=()=>download('mi-practica.'+(blob.type.includes('mp4')?'m4a':'webm'),blob);}});}
function toggleRecording(){if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){toast('Este navegador o dirección no admite grabación. Usá localhost o HTTPS.');return;}ensureAudio();if(audioCapture.isRecording())audioCapture.stop();else if(!audioCapture.isPending()){if(audioURL)URL.revokeObjectURL(audioURL);audioURL=null;$('#playback').hidden=true;$('#downloadAudio').hidden=true;audioCapture.start();}}
function bankBase(){return ({curated:CURATED.map(x=>x.word),ar:CURATED.filter(x=>x.region==='ar').map(x=>x.word),fav:state.favorites,custom:state.custom})[$('#source').value]||allWords}
function renderBank(){const results=C.filterWords(bankBase(),$('#search').value,$('#contains').value),pages=Math.max(1,Math.ceil(results.length/48));page=Math.min(page,pages-1);$('#bankCount').textContent=`${results.length.toLocaleString('es-AR')} ${results.length===1?'palabra':'palabras'} · ${allWords.length.toLocaleString('es-AR')} en el banco instalado`;$('#wordList').replaceChildren();for(const w of results.slice(page*48,page*48+48)){const b=document.createElement('button');b.textContent=w;b.onclick=()=>{choose(w);go('practica')};$('#wordList').append(b)}if(!results.length)$('#wordList').textContent='No hay coincidencias. Podés agregar la palabra abajo.';$('#pageNumber').textContent=`Página ${page+1} de ${pages}`;$('#prevPage').disabled=page===0;$('#nextPage').disabled=page===pages-1}
