$('#addForm').onsubmit=e=>{e.preventDefault();const w=C.normalize($('#newWord').value);if(!C.validWord(w)){toast('Usá letras españolas, espacios o guiones; hasta 50 caracteres.');return}const result=addWords([w]);$('#newWord').value='';toast(result.saved?'Palabra guardada en este navegador.':'Palabra en memoria. Exportá una copia para conservarla.')};$('#importWords').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>2*1024*1024){$('#importStatus').textContent='El archivo supera 2 MB.';return}try{const words=C.parseList(await f.text()),count=addWords(words);$('#importStatus').textContent=`${count.count} palabras agregadas ${count.saved?'y guardadas':'solo en memoria; exportá una copia para conservarlas'}. Se omiten duplicados, líneas inválidas y entradas que superen el límite de 50.000 palabras propias.`}catch{$('#importStatus').textContent='No se pudo leer el archivo.'}e.target.value=''};
