$('#exportProgress').onclick=()=>download('habla-registro.json',new Blob([Store.serialize(state)],{type:'application/json'}));$('#clearProgress').onclick=()=>$('#deleteConfirm').hidden=false;$('#cancelDelete').onclick=()=>$('#deleteConfirm').hidden=true;$('#confirmDelete').onclick=()=>{state.history=[];const saved=save();renderProgress();$('#deleteConfirm').hidden=true;toast(saved?'Registro borrado.':'Registro quitado solo de esta sesión; no se pudo guardar el cambio.')};
const canvas=$('#canvas'),ctx=canvas.getContext('2d');
let canvasFrame=0;const drawingDrafts=new Map();let drawingKey=$('#traceText').value+'|'+$('#letterStyle').value;
function stashDrawing(){if(strokes.length)drawingDrafts.set(drawingKey,strokes);else drawingDrafts.delete(drawingKey);if(drawingDrafts.size>100)drawingDrafts.delete(drawingDrafts.keys().next().value);}
function recallDrawing(){drawingKey=$('#traceText').value+'|'+$('#letterStyle').value;strokes=drawingDrafts.get(drawingKey)||[];pointer=null;activeStroke=null;}

function draw(){if($('#cuaderno').hidden)return;let rect=canvas.getBoundingClientRect(),dpr=window.devicePixelRatio||1;canvas.width=rect.width*dpr;canvas.height=rect.height*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);let w=rect.width,h=rect.height;ctx.fillStyle='#fffdf8';ctx.fillRect(0,0,w,h);ctx.strokeStyle='#dce3db';ctx.lineWidth=1;for(let y of [h*.25,h*.52,h*.78]){ctx.setLineDash(y===h*.52?[5,6]:[]);ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke()}ctx.setLineDash([]);let text=$('#traceText').value,style=$('#letterStyle').value;if(style==='upper')text=text.toLocaleUpperCase('es');else text=text.toLocaleLowerCase('es');let family=style==='cursive'?'cursive':'Arial',size=Math.min(110,h*.4);ctx.font=`${size}px ${family}`;while(ctx.measureText(text).width>w-35&&size>14){size-=2;ctx.font=`${size}px ${family}`}ctx.fillStyle='#b6c5b8';ctx.fillText(text,18,h*.73);ctx.lineCap='round';ctx.lineJoin='round';for(const s of strokes){ctx.strokeStyle='#245c50';ctx.lineWidth=s.width;ctx.beginPath();s.points.forEach((p,i)=>{if(i)ctx.lineTo(p[0]*w,p[1]*h);else ctx.moveTo(p[0]*w,p[1]*h)});if(s.points.length===1){const p=s.points[0];ctx.lineTo(p[0]*w+.1,p[1]*h+.1)}ctx.stroke()}}
function point(e){const r=canvas.getBoundingClientRect();return [(e.clientX-r.left)/r.width,(e.clientY-r.top)/r.height]}
canvas.onpointerdown=e=>{if(pointer!==null||e.button>0)return;pointer=e.pointerId;canvas.setPointerCapture(pointer);activeStroke={width:Number($('#penSize').value),points:[point(e)]};strokes.push(activeStroke);draw()};canvas.onpointermove=e=>{if(pointer!==e.pointerId||!activeStroke)return;activeStroke.points.push(point(e));if(activeStroke.points.length>4000)activeStroke.points=activeStroke.points.filter((_,i)=>i%2===0);if(!canvasFrame)canvasFrame=requestAnimationFrame(()=>{canvasFrame=0;draw();})};function endPointer(e){if(pointer===e.pointerId){pointer=null;activeStroke=null}}canvas.onpointerup=endPointer;canvas.onpointercancel=endPointer;canvas.onlostpointercapture=endPointer;
new ResizeObserver(()=>draw()).observe(canvas);for(const id of ['traceText','letterStyle'])$('#'+id).addEventListener('input',()=>{stashDrawing();recallDrawing();$('#traceKeyboard').value='';$('#traceFeedback').textContent='';draw()});$('#undo').onclick=()=>{strokes.pop();draw()};$('#clearCanvas').onclick=()=>{strokes=[];stashDrawing();draw()};$('#saveDrawing').onclick=()=>canvas.toBlob(blob=>{if(blob)download('habla-caligrafia.png',blob)});$('#traceKeyboard').oninput=()=>$('#traceFeedback').textContent=C.spelling($('#traceKeyboard').value,$('#traceText').value);$('#doneTrace').onclick=()=>{if(!$('#traceText').value.trim()){toast('Escribí un modelo antes de registrar la práctica.');return}record('Caligrafía',$('#traceText').value)};
