function restoreCancel(){restoreGeneration++;pendingRestore=null;$('#restorePreview').hidden=true;$('#restoreFile').value='';}
$('#restoreFile').onchange=async e=>{const file=e.target.files?.[0],generation=++restoreGeneration;pendingRestore=null;$('#restorePreview').hidden=true;if(!file)return;try{if(file.size>8*1024*1024)throw Error('La copia supera 8 MB.');const text=await file.text();if(generation!==restoreGeneration)return;const merged=Store.merge(state,Store.parse(text));pendingRestore=merged.state;$('#restoreSummary').textContent=`Resultado: ${pendingRestore.history.length} actividades, ${pendingRestore.favorites.length} favoritas y ${pendingRestore.custom.length} palabras propias. ${merged.omitted?`${merged.omitted} actividades antiguas quedarían fuera del límite de 1.000.`:''}`;$('#restorePreview').hidden=false;$('#restoreStatus').textContent='Copia validada. Revisá el resumen antes de confirmar.';}catch(err){$('#restoreStatus').textContent=err.message;}e.target.value='';};
$('#cancelRestore').onclick=restoreCancel;
$('#confirmRestore').onclick=()=>{if(!pendingRestore)return;try{const raw=storageAccess.getItem(Store.KEY);download('habla-antes-de-restaurar.json',new Blob([raw||Store.serialize(state)],{type:'application/json'}));if(raw!==lastSavedRaw)throw Error("El registro cambió en otra pestaña. Cancelá, recargá y volvé a importar.");Store.write(storageAccess,pendingRestore);lastSavedRaw=storageAccess.getItem(Store.KEY);state=pendingRestore;storageLocked=false;allWords=[...new Set([...(window.LEXICON||[]),...CURATED.map(x=>x.word),...state.custom])].sort((a,b)=>a.localeCompare(b,'es'));restoreCancel();$('#storageNotice').hidden=true;$('#restoreStatus').textContent='Copia restaurada y guardada.';renderProgress();renderBank();updateFavorite();}catch(err){$('#restoreStatus').textContent='No se aplicó la restauración: '+err.message;}};
if(loaded.locked){$('#storageNotice').hidden=false;$('#storageNotice').textContent='El registro previo no se pudo leer. Está protegido contra sobrescritura. Podés descargarlo o restaurar una copia válida. La práctica actual queda en memoria.';if(loaded.raw!==null){$('#downloadOriginal').hidden=false;$('#downloadOriginal').onclick=()=>download('habla-registro-original.json',new Blob([loaded.raw],{type:'application/json'}));}toast('Revisá Mi recorrido: el guardado local necesita atención.');}

const Play=HablaPlay;
let completedStations=[],journeyCelebrated=false;
function stationName(station){return $('#journeyStyle').value==='focus'?station.short:station.title;}
function renderMap(){const result=Play.progress(completedStations,Number($('#journeyGoal').value));$('#stationMap').replaceChildren();for(const [index,station]of Play.STATIONS.entries()){const button=document.createElement('button');button.className='station '+station.color+(result.completed.includes(station.id)?' explored':'');const symbol=document.createElement('span');symbol.className='station-symbol';symbol.innerHTML=HablaIcons.svg(({'Pronunciación':'sound','Escritura':'pencil','Sílabas':'pieces','Escucha de pares':'sound','Caligrafía':'wave'})[station.id]);const number=document.createElement('span');number.className='station-number';number.textContent=String(index+1).padStart(2,'0');const title=document.createElement('strong');title.textContent=stationName(station);const text=document.createElement('span');text.className='station-description';text.textContent=$('#journeyStyle').value==='focus'?({'Pronunciación':'Modelo, repetición y escucha propia','Escritura':'Copia o dictado con comparación','Sílabas':'Orden y construcción de palabras','Escucha de pares':'Comparación de palabras cercanas','Caligrafía':'Modelo y trazado libre'})[station.id]:station.short;const status=document.createElement('span');status.className='station-status';status.textContent=result.completed.includes(station.id)?'✓ Explorada · volver a jugar':'Entrar →';button.append(symbol,number,title,text,status);button.onclick=()=>openStation(station);$('#stationMap').append(button);}$('#journeyLabel').textContent=`${Math.min(result.count,result.target)} de ${result.target} estaciones exploradas`;$('#journeyMessage').textContent=result.done?'Tu recorrido está completo. Podés descansar o seguir explorando.':'Podés hacer una, varias o parar cuando quieras.';$('.journey-meter').setAttribute('aria-valuemax',result.target);$('.journey-meter').setAttribute('aria-valuenow',Math.min(result.count,result.target));$('#journeyFill').style.width=(result.ratio*100)+'%';}
function openStation(station){if(station.mode)mode=station.mode;if(station.mode==='silabas'&&!current.syllables)choose(CURATED[0].word);go(station.page);}
function visitStation(kind){completedStations.push(kind);renderMap();if(Play.progress(completedStations,Number($('#journeyGoal').value)).done&&!journeyCelebrated){journeyCelebrated=true;$('#journeyComplete').hidden=false;}}
$('#journeyStyle').onchange=()=>{document.body.dataset.journey=$('#journeyStyle').value;$('#adventureIntro').textContent=$('#journeyStyle').value==='focus'?'Elegí una actividad, practicá a tu ritmo y llevá un registro de lo que explorás.':'Escuchá, armá y dibujá palabras. Elegí por dónde empezar: cada intento cuenta.';$('#mapTitle').textContent=$('#journeyStyle').value==='focus'?'Tu espacio de práctica':'Tu mapa de hoy';$('#companionMessage').textContent=$('#journeyStyle').value==='focus'?'Elegí un objetivo posible. Practicá sin apuro y tomá una pausa cuando la necesites.':'Luma te acompaña. No hace falta hacerlo perfecto para disfrutar el camino.';renderMap();};
$('#journeyGoal').onchange=renderMap;
$('#startAdventure').onclick=()=>openStation(Play.STATIONS[0]);
$('#resetJourney').onclick=()=>{completedStations=[];journeyCelebrated=false;$('#journeyComplete').hidden=true;renderMap();toast('Nuevo recorrido. Tu historial sigue guardado.');};
$('#dismissComplete').onclick=()=>$('#journeyComplete').hidden=true;
$('#quietToggle').onclick=()=>{const quiet=document.body.classList.toggle('quiet-mode');$('#quietToggle').setAttribute('aria-pressed',quiet);$('#quietToggle').textContent=quiet?'Calma visual activada':'Calma visual';traceGuide?.refresh();};
function renderSyllables(){const target=$('#activity');target.innerHTML='<h3>Un puente de sílabas.</h3><p>Elegí las piezas en orden para armar la palabra. Podés usar el dedo, el mouse o Tab y Enter.</p><div id="syllableAnswer" class="syllable-answer" aria-label="Sílabas elegidas" aria-live="polite"></div><div id="syllablePieces" class="syllable-pieces" role="group" aria-label="Elegir sílabas"></div><div class="inline"><button id="syllableUndo">↶ Quitar la última</button><button id="syllableModel" aria-pressed="false">Mostrar modelo</button></div><p id="syllableFeedback" class="feedback" role="status"></p>';
if(!current.syllables){target.replaceChildren();const p=document.createElement('p');p.textContent='Esta palabra no tiene sílabas revisadas. Elegí una palabra de la selección para jugar.';const b=document.createElement('button');b.textContent='Jugar con perro';b.onclick=()=>choose('perro');target.append(p,b);return;}
const parts=current.syllables.split('-'),pieces=Play.shuffled(parts);let selected=[],finished=false;$('#currentWord').style.visibility='hidden';$('#syllables').style.visibility='hidden';$('#syllableModel').onclick=()=>{const reveal=$('#currentWord').style.visibility==='hidden';$('#currentWord').style.visibility=reveal?'':'hidden';$('#syllables').style.visibility=reveal?'':'hidden';$('#syllableModel').textContent=reveal?'Ocultar modelo':'Mostrar modelo';$('#syllableModel').setAttribute('aria-pressed',reveal);};
function update(){const answer=selected.map(id=>parts[id]);$('#syllableAnswer').textContent=answer.length?answer.join(' · '):'Tus sílabas van acá';$$('#syllablePieces button').forEach(b=>b.disabled=finished||selected.includes(Number(b.dataset.id)));$('#syllableUndo').disabled=finished||!selected.length;if(Play.matches(parts,answer)){finished=true;$('#syllableFeedback').textContent='¡Construiste la palabra! Leela o escuchala a tu ritmo.';$('#currentWord').style.visibility='';$('#syllables').style.visibility='';record('Sílabas');$$('#syllablePieces button').forEach(b=>b.disabled=true);$('#syllableUndo').disabled=true;}else $('#syllableFeedback').textContent=answer.length===parts.length?'Las piezas están completas. Compará con el modelo y probá otro orden.':'Escuchá la palabra y elegí la próxima pieza.';}
for(const piece of pieces){const b=document.createElement('button');b.textContent=piece.text;b.dataset.id=piece.id;b.onclick=()=>{selected.push(piece.id);update();const next=$$('#syllablePieces button').find(x=>!x.disabled);if(next)next.focus({preventScroll:true});else if(!finished)$('#syllableUndo').focus({preventScroll:true});};$('#syllablePieces').append(b);}$('#syllableUndo').onclick=()=>{selected.pop();update();};update();}
document.body.dataset.journey='explore';$('#journeyStyle').value='explore';renderMap();

window.addEventListener('hashchange',()=>go(location.hash.slice(1)||'aventura'));

// Resumen por período: usa el mismo registro en memoria, nunca modifica sus entradas.
function reportNode(tag,text,className){const node=document.createElement(tag);if(text!==undefined)node.textContent=text;if(className)node.className=className;return node;}
function reportDate(value){const [y,m,d]=value.split('-');return `${d}/${m}/${y}`;}
function renderReport(){
  const preview=$('#reportPreview');preview.replaceChildren();$('#printReport').disabled=true;
  try{
    const report=HablaReport.summarize(state.history,$('#reportFrom').value,$('#reportTo').value),article=reportNode('article',undefined,'practice-report');
    article.append(reportNode('p','HABLA LOCAL · REGISTRO DE PRÁCTICA','eyebrow'),reportNode('h2','Palabra a palabra'),reportNode('p',`Período: ${reportDate(report.from)} al ${reportDate(report.to)} · Fechas del dispositivo.`),reportNode('p',`${report.total} ${report.total===1?'actividad':'actividades'} · ${report.words.length} ${report.words.length===1?'palabra diferente':'palabras diferentes'} · ${report.days} ${report.days===1?'día':'días'} con práctica.`,'report-totals'));
    if(!report.total)article.append(reportNode('p','No hay actividades en este período. Probá con otras fechas o elegí Todo el registro.'));
    else{
      article.append(reportNode('h3','Actividades registradas'));const list=reportNode('ul');for(const [kind,count]of report.kinds)list.append(reportNode('li',`${kind}: ${count}`));article.append(list,reportNode('h3','Palabras exploradas'));
      const table=reportNode('table'),caption=reportNode('caption','Cantidad de actividades por palabra; puede incluir varias prácticas de la misma palabra.'),head=reportNode('thead'),header=reportNode('tr');for(const title of ['Palabra','Actividades','Prácticas']){const th=reportNode('th',title);th.scope='col';header.append(th);}head.append(header);const body=reportNode('tbody');for(const word of report.words){const tr=reportNode('tr');tr.append(reportNode('th',word.word),reportNode('td',String(word.count)),reportNode('td',word.kinds.join(', ')));tr.firstChild.scope='row';body.append(tr);}table.append(caption,head,body);article.append(table);
    }
    article.append(reportNode('p','Resumen descriptivo del registro conservado en este navegador (máximo 1.000 actividades). No evalúa pronunciación, motricidad, aciertos ni resultados terapéuticos. No incluye audios ni dibujos.','report-note'),reportNode('p',`Preparado el ${new Date().toLocaleString('es-AR')}.`,'muted'));preview.append(article);preview.hidden=false;$('#reportStatus').textContent=report.total?'Resumen listo. Revisalo antes de imprimir o compartir.':'No hay actividades en el período elegido.';$('#printReport').disabled=false;return true;
  }catch(error){preview.hidden=true;$('#reportStatus').textContent=error.message;return false;}
}
function invalidateReport(){const wasVisible=!$('#reportPreview').hidden;$('#reportPreview').hidden=true;$('#reportPreview').replaceChildren();$('#printReport').disabled=true;$('#reportStatus').textContent=wasVisible?'Fechas cambiadas. Volvé a pulsar Ver resumen.':'';}
const reportToday=new Date(),reportStart=new Date();reportStart.setDate(reportStart.getDate()-6);$('#reportFrom').value=HablaReport.dayKey(reportStart);$('#reportTo').value=HablaReport.dayKey(reportToday);
$('#reportForm').onsubmit=e=>{e.preventDefault();renderReport();};for(const id of ['reportFrom','reportTo'])$('#'+id).oninput=invalidateReport;
$('#reportAll').onclick=()=>{const dates=state.history.map(x=>x.at);$('#reportFrom').value=HablaReport.dayKey(new Date(dates.length?Math.min(...dates):Date.now()));$('#reportTo').value=HablaReport.dayKey(new Date(dates.length?Math.max(...dates):Date.now()));renderReport();};
function removePrintSheet(){$$('.print-sheet').forEach(s=>s.remove());}
window.addEventListener('afterprint',removePrintSheet);
$('#printReport').onclick=()=>{if(!renderReport())return;removePrintSheet();const sheet=reportNode('section',undefined,'print-sheet report-print');sheet.append($('#reportPreview article').cloneNode(true));document.body.append(sheet);try{window.print();}catch{removePrintSheet();$('#reportStatus').textContent='La impresión no está disponible. Podés consultar el resumen en pantalla y exportar el registro JSON.';}};

traceGuide=HablaTracing.mount($('#traceGuide'));
$('#guideUseInitial').onclick=()=>{const letter=HablaTracing.initial($('#traceText').value);if(!letter){toast('Escribí un texto que empiece con una letra española.');return;}traceGuide.setLetter(letter);};
window.addEventListener('pagehide',()=>traceGuide?.pause());
